    insert into explore_content (kind, title, subtitle, body, url, tags, institution, sort, source, status)
    values
  ('scholarships', 'SUSI maintenance and fee grants', 'The main national grant for full-time students. Means-tested.', 'SUSI pays two kinds of grant. The maintenance grant helps with living costs and is paid into your bank account. The fee grant pays tuition if you are not on the Free Fees scheme, and can cover the Student Contribution and essential field trips. SUSI says applications for 2026/27 are closed and there is a late application process. We could not find the 2027/28 opening date, so watch susi.ie. SUSI phone: 0818 888 777. Checked November 2026. Confirm details on the official page.', 'https://www.susi.ie/how-to-apply/what-grants-are-available/', array['funding','undergraduate','means-tested','national']::text[], null, 10, 'ubp', 'published'),
  ('scholarships', 'Student Assistance Fund', 'Hardship money through your college. Does not cover tuition.', 'Run by the HEA and paid out by your college. It can help with books, class materials, rent, bills, food, travel, childcare and medical costs. It does not cover tuition or registration fees. It is for courses at levels 6 to 10, and part-time students can apply too. Ask your college access or student services office, and apply early because some colleges close the call. Checked November 2026. Confirm details on the official page.', 'https://hea.ie/funding-governance-performance/funding/student-finance/student-assistance-fund/', array['funding','undergraduate','hardship','means-tested']::text[], null, 20, 'ubp', 'published'),
  ('scholarships', 'Fund for Students with Disabilities', 'Pays for supports in college. Not cash to you.', 'The HEA gives money to colleges so they can provide supports for students with disabilities. It can cover assistive technology, equipment and software, non-medical helpers, academic or learning support, deaf supports and transport. Ask your college disability support service to assess what you need. Checked November 2026. Confirm details on the official page.', 'https://hea.ie/policy/access/fund-for-students-with-disabilities/', array['funding','disability','undergraduate','access']::text[], null, 30, 'ubp', 'published'),
  ('scholarships', '1916 Bursary Fund', 'For students from groups under-represented in college. Means-tested.', 'A bursary for students who are most socio-economically disadvantaged and from groups under-represented in higher education. You must meet the financial, priority group and college entry rules. Each college has a limited number and gives them to the people with the greatest need. Ask the Access Office at your college how to apply. Checked November 2026. Confirm details on the official page.', 'https://hea.ie/funding-governance-performance/funding/student-finance/1916-bursary/', array['funding','undergraduate','means-tested','access']::text[], null, 40, 'ubp', 'published'),
  ('scholarships', 'Trinity Access Programmes', 'Entry routes and funding at Trinity for under-represented groups.', 'Trinity Access Programmes list financial support including the Student Scholarship Fund, the 1916 Bursary, the University of Sanctuary Scholarship, the Laidlaw Trailblazer Scholarship and support for Traveller and Roma students. Entry routes include the TAP Foundation Course, HEAR, further education routes and mature student routes. Checked November 2026. Confirm details on the official page.', 'https://www.tcd.ie/trinityaccess/', array['funding','access','undergraduate','mature']::text[], 'Trinity College Dublin', 50, 'ubp', 'published'),
  ('scholarships', 'DCU Access Service', 'Entry routes and supports at DCU for under-represented groups.', 'Entry routes are HEAR, the Access DCU Entry Route, the Mature Students Entry Route and the PLC/QQI route. Supports after you start include an Access orientation programme and Access to the Workplace. DCU also runs subsidised campus accommodation as a separate scheme. The Access DCU Entry Route was closed for 2026. Email access@dcu.ie. Checked November 2026. Confirm details on the official page.', 'https://www.dcu.ie/access', array['funding','access','undergraduate','mature']::text[], 'Dublin City University', 60, 'ubp', 'published'),
  ('scholarships', 'DCU Sport Scholarships', 'A bursary of up to 4,000 euro plus sport supports.', 'For students with high-level sporting achievement, and committed students in athletics, Gaelic games, rugby or soccer. Benefits vary by grade and include a bursary of up to 4,000 euro, sports complex membership, priority on-campus accommodation, mentoring and strength and conditioning. 2026-27 applications are closed. The 2027-28 call opens 1 February 2027 and closes 1 May 2027 at 5pm. Late applications are not accepted. Checked November 2026. Confirm details on the official page.', 'https://www.dcu.ie/sportscholarships', array['funding','sport','undergraduate']::text[], 'Dublin City University', 70, 'ubp', 'published'),
  ('scholarships', 'UL Sports Scholarships', 'Gold, Silver and Bronze awards at the University of Limerick.', 'Gold covers a training grant, on-campus accommodation, the full registration fee and sports science support. Silver is the same with 50 percent of the registration fee. Bronze covers a training grant, coaching and gym membership. You must belong to a national governing body of sport recognised by the Irish Sports Council. September 2027 applications open 4 January 2027 and close 5 March 2027. Email sportsscholarships@ul.ie. Checked November 2026. Confirm details on the official page.', 'https://www.ul.ie/sportsscholarships', array['funding','sport','undergraduate']::text[], 'University of Limerick', 80, 'ubp', 'published'),
  ('scholarships', 'TU Dublin Athlete Support Programme', 'Sports scholarship with fee, accommodation and training supports.', 'Benefits can include reduced CAO points of up to 10 percent, accommodation support, a fee waiver and a financial award valued case by case. You must compete at regional, county, national or international level in a sport recognised by Sport Ireland. The 2026/27 call is closed. Watch the page for the next call. Email performancesport@tudublin.ie. Checked November 2026. Confirm details on the official page.', 'https://www.tudublin.ie/study/undergraduate/scholarships/sports-scholarships/', array['funding','sport','undergraduate']::text[], 'TU Dublin', 90, 'ubp', 'published'),
  ('scholarships', 'UCD Sport Scholarship', 'For students with a place at UCD who compete in a sport.', 'Awarded once you have a place on a UCD programme. You need two references, one academic and one sporting, and one application per sport. Applications for September 2026 entry ran from 1 February to 27 March 2026, so watch the page in early 2027. UCD also runs a graduate sport scholarship. Email sport@ucd.ie. Checked November 2026. Confirm details on the official page.', 'https://www.ucd.ie/sport/scholarshipsinfokeydates/ucdsportscholarship', array['funding','sport','undergraduate']::text[], 'University College Dublin', 100, 'ubp', 'published'),
  ('scholarships', 'Maynooth Sport Scholarships', 'For students with a strong sporting record.', 'For students who play an active part in the relevant Maynooth club and compete for the university at inter-varsity level. Open to undergraduates and postgraduates. The yearly closing date has been 1 April, so check the page for the current date. Contact your sport''s development officer. Checked November 2026. Confirm details on the official page.', 'https://www.maynoothuniversity.ie/study-maynooth/undergraduate-studies/scholarships/sport-scholarships', array['funding','sport','undergraduate']::text[], 'Maynooth University', 110, 'ubp', 'published'),
  ('scholarships', 'Erasmus+ study and traineeships abroad', 'EU programme to study or train abroad. Run in Ireland by the HEA.', 'Erasmus+ lets higher education students spend time studying or on a traineeship in another country. Ask your college international office how to apply and what funding you could get. Email erasmus@hea.ie for programme questions. Checked November 2026. Confirm details on the official page.', 'https://erasmusirelandhe.ie/', array['funding','undergraduate','abroad']::text[], null, 120, 'ubp', 'published'),
  ('scholarships', 'Springboard+', 'Subsidised courses from level 6 to 9. Free for some people.', 'Springboard+ courses run from level 6 certificates to level 9 postgraduate qualifications. Courses are free for unemployed people and people returning to the workforce. Employed learners usually pay 10 percent of the fee. Micro-credentials are 50 percent subsidised for everyone. You must be in Ireland and not on a VPN to use springboardcourses.ie. Checked November 2026. Confirm details on the official page.', 'https://hea.ie/skills-engagement/springboard/', array['funding','mature','upskilling','part-time']::text[], null, 130, 'ubp', 'published'),
  ('scholarships', 'Irish Cancer Society Summer Studentships', '2,500 euro for a summer cancer research project.', 'For undergraduates who want to do a cancer research project. There are two streams, one for biomedical and life science degrees and one for social science, nursing and allied health. The award is 2,500 euro for a placement of up to eight weeks starting in June. Applications open in the first quarter each year. Checked November 2026. Confirm details on the official page.', 'https://cancer.ie/cancer-research/researchers-hub/apply-for-funding/summer-studentships', array['funding','undergraduate','research']::text[], null, 140, 'ubp', 'published'),
  ('scholarships', 'All Ireland Scholarships', '125 scholarships a year across all 32 counties.', 'Set up in 2008 to support gifted young students so they can take part in university life. 125 scholarships are awarded each year. Read the Am I Eligible page on the site before you register. Email info@allirelandscholarships.com. Checked November 2026. Confirm details on the official page.', 'https://www.allirelandscholarships.com/', array['funding','undergraduate','school-leaver']::text[], null, 150, 'ubp', 'published'),
  ('scholarships', 'Naughton Scholarships', '36 scholarships a year for science, engineering and technology.', 'For Leaving Certificate students from any county in the Republic of Ireland who go on to study engineering, science or technology at a publicly funded third-level college. At least one winner comes from each county. The 2026 call opened on 2 March 2026. Read the terms and conditions on the site before you apply. Checked November 2026. Confirm details on the official page.', 'https://www.thenaughtonfoundation.com/', array['funding','undergraduate','STEM','school-leaver']::text[], null, 160, 'ubp', 'published'),
  ('scholarships', 'SVP Education and Training Bursary', 'Help for students of any age who face financial difficulty.', 'For anyone who has trouble starting or staying in third-level education or training. It covers recognised programmes, with a focus on people starting out, including degrees, training courses and apprenticeships. You must show you have already applied for all state funding and other grants. Contact your local SVP office. Awards depend on funding. Checked November 2026. Confirm details on the official page.', 'https://www.svp.ie/what-we-do/education-grants.aspx', array['funding','undergraduate','apprentice','hardship']::text[], null, 170, 'ubp', 'published'),
  ('scholarships', 'Uversity scholarships for adult learners', '5,000 or 7,000 euro a year for mature students.', 'For adults doing a first bachelor''s degree at one of 36 colleges on the island of Ireland. The award is 5,000 euro a year, or 7,000 euro a year if you have dependent children, paid monthly for up to four years. You must be 23 or older by 1 January and show financial need. Applications for 2027/28 open 1 February 2027 and close 31 March 2027. Email apply@uversity.org. Checked November 2026. Confirm details on the official page.', 'https://www.uversity.org/the-scholarships/', array['funding','mature','undergraduate','means-tested']::text[], null, 180, 'ubp', 'published'),
  ('scholarships', 'Credit Union Plus student and apprentice draw', 'Twelve winners get 1,500 euro each. Members only.', 'For members of Credit Union Plus starting a full-time PLC, diploma or degree, or an approved apprenticeship. You must be a member before 31 July and return the form by 30 September. The page showed twelve winners at 1,500 euro each for the 2025 round, so check the current amount. Checked November 2026. Confirm details on the official page.', 'https://creditunionplus.ie/student-apprentice-prize-draw/', array['funding','apprentice','undergraduate']::text[], null, 190, 'ubp', 'published'),
  ('scholarships', 'NUI Equal Educational Opportunities Scheme', 'Support for students in economically disadvantaged circumstances.', 'A National University of Ireland scheme that is nomination-based. That means you cannot apply directly. Ask your college access office whether you could be put forward. NUI phone: +353 1 439 2424. Checked November 2026. Confirm details on the official page.', 'https://www.nui.ie/what-we-do/nui-awards/inclusion-grants/the-nui-equal-educational-opportunities-scheme/', array['funding','undergraduate','means-tested','access']::text[], null, 200, 'ubp', 'published'),
  ('scholarships', 'Back to Education Allowance', 'Income support if you start a full-time course on a welfare payment.', 'For people on certain social welfare payments who start a full-time second or third level course. Apply before your course starts. The Department of Social Protection decides. You cannot get it together with the maintenance grant from SUSI, but you can still get a SUSI fee grant. Checked November 2026. Confirm details on the official page.', 'https://www.gov.ie/en/service/418e3f-back-to-education-allowance', array['funding','mature','welfare']::text[], null, 210, 'ubp', 'published'),
  ('scholarships', 'Trinity Foundation Scholarship', 'Exam-based award for Senior Freshmen at Trinity.', 'Any fully registered Trinity Senior Freshman can sit the Foundation Scholarship exams. It is awarded on exam performance only, and there is a limit of 70 Foundation Scholars. The last published call ran 29 September to 15 October 2025, with exams on 5 to 9 January 2026. Watch the page for the next call. Checked November 2026. Confirm details on the official page.', 'https://www.tcd.ie/academicregistry/exams/scholarship/faq/', array['funding','undergraduate','merit']::text[], 'Trinity College Dublin', 220, 'ubp', 'published'),
  ('scholarships', 'UCC scholarships', 'Quercus awards, KPMG accounting scholarships and more.', 'UCC lists many undergraduate awards. They include the Quercus scholarships for active citizenship, creative and performing arts, innovation and entrepreneurship, and sport. They also include KPMG All Rise scholarships for accounting and Dairygold bursaries for agri-food students. Status changes through the year, so open each award to see if it is open. Checked November 2026. Confirm details on the official page.', 'https://www.ucc.ie/en/scholarships/all/alluccsch/', array['funding','undergraduate','merit']::text[], 'University College Cork', 230, 'ubp', 'published'),
  ('scholarships', 'University of Galway access funds and scholarships', 'A list of bursaries and scholarships at Galway.', 'The Access Centre lists the 1916 Bursary Fund, the Student Accommodation Assistance Fund, the Marie Birkett Bursary, the Financial Aid Fund, the University of Sanctuary award and several named undergraduate scholarships. Open each one to see who can apply. Checked November 2026. Confirm details on the official page.', 'https://www.universityofgalway.ie/access/scholarshipsfunds/', array['funding','access','undergraduate']::text[], 'University of Galway', 240, 'ubp', 'published'),
  ('scholarships', 'NCBI Gerard Byrne Bursary', '1,500 euro a year for students with a vision impairment.', 'The HEA lists this bursary for students with a vision impairment in full-time third-level education. It is 1,500 euro a year for the length of an undergraduate degree. NCBI''s old website now redirects to vi.ie, so check there for how to apply. Checked November 2026. Confirm details on the official page.', 'https://hea.ie/funding-governance-performance/funding/student-finance/other-finance-bursaries-scholarships/', array['funding','disability','undergraduate']::text[], null, 250, 'ubp', 'published'),
  ('scholarships', 'SIPTU Education and Development Support Scheme', 'For SIPTU members who want to upskill.', 'The HEA lists this scheme for SIPTU members. It supports further and higher learning to improve employability and career progression. Ask your SIPTU branch how to apply. Checked November 2026. Confirm details on the official page.', 'https://hea.ie/funding-governance-performance/funding/student-finance/other-finance-bursaries-scholarships/', array['funding','workers','mature']::text[], null, 260, 'ubp', 'published'),
  ('scholarships', 'NISO Occupational Health and Safety Bursary', 'For under-represented students who want a career in health and safety.', 'The HEA lists a 2026/27 bursary from NISO. It supports students from under-represented groups who are entering higher education and want to work in occupational health and safety. Look up NISO for the current rules. Checked November 2026. Confirm details on the official page.', 'https://hea.ie/funding-governance-performance/funding/student-finance/other-finance-bursaries-scholarships/', array['funding','access','undergraduate']::text[], null, 270, 'ubp', 'published'),
  ('scholarships', 'Irish Refugee Education Fund', 'Helps people in the asylum process get into further education.', 'Set up in 2015 with support from the Community Foundation for Ireland. The HEA lists it as a fund to help people in the asylum process access further education. Ask the Irish Refugee Council about the current process. Checked November 2026. Confirm details on the official page.', 'https://hea.ie/funding-governance-performance/funding/student-finance/other-finance-bursaries-scholarships/', array['funding','access','asylum']::text[], null, 280, 'ubp', 'published'),
  ('discounts', 'Student Leap Card', '50 percent off public transport for full-time students.', 'TFI says you get 50 percent off public transport fares with a valid Young Adult or Student Leap Card. Dublin Bus lists the Student card for full-time students aged 16 to 18 or 26 and over. Order online at leapcard.ie, then go to a Student Leap Agent to prove you are a student and collect the card. Age rules have changed before, so check leapcard.ie. Checked November 2026. Confirm details on the official page.', 'https://www.dublinbus.ie/journey-information/college-transport-hub/save-with-public-transport', array['transport','discount','leap-card']::text[], null, 10, 'ubp', 'published'),
  ('discounts', 'Young Adult Leap Card', 'Same 50 percent off, for everyone aged 19 to 25.', 'If you are 19 to 25 you can get a Young Adult Leap Card whether or not you are a student. It gives the same 50 percent off fares as the Student card. Order it at leapcard.ie. You need a valid Young Adult or Student Leap Card to get TFI Go fares on commercial bus operators. Checked November 2026. Confirm details on the official page.', 'https://www.transportforireland.ie/fares/50-discount-for-young-adult-and-student-leap-card-holders-on-commercial-bus-operators/', array['transport','discount','leap-card']::text[], null, 20, 'ubp', 'published'),
  ('discounts', 'Irish Rail student and young adult fares', '50 percent off InterCity adult fares.', 'Only the TFI Student Leap Card, the TFI Young Adult (19-25) Leap Card and the Translink yLink card are valid for student fares. The Leap card is used as proof of your discount. You cannot tag on and pay for InterCity journeys with a Leap card. Always book a single ticket, not a return. Without the right ticket and card the fine is 100 euro plus the fare. Checked November 2026. Confirm details on the official page.', 'https://www.irishrail.ie/en-ie/rail-fares-and-tickets/students', array['transport','discount','rail']::text[], null, 30, 'ubp', 'published'),
  ('discounts', 'Luas student fares', 'Cheaper Luas fares with a Student Leap Card.', 'At the time of checking, the Luas student 90 Minute Fare was 1.00 euro against 2.00 euro for adults. The student Short Fare was 0.75 euro against 1.50 euro. Multi-operator caps on the card across Dublin Bus, Luas, DART and Commuter Rail were 3.00 euro a day and 12.00 euro a week. You must be studying in Ireland and eligible for a Student Leap Card. Checked November 2026. Confirm details on the official page.', 'https://www.luas.ie/student-tickets', array['transport','discount','dublin']::text[], null, 40, 'ubp', 'published'),
  ('discounts', '50 percent off coach services', 'Student and Young Adult Leap Card discount on many private coach operators.', 'Participating operators include Aircoach, Expressway, CityLink, Dublin Coach, J.J. Kavanagh, Dublin Express and Wexford Bus. Each operator uses a different method. Some take the discount from your Leap card, some sell discounted tickets online, and some use the TFI Go app. Carry your card when you travel. Checked November 2026. Confirm details on the official page.', 'https://www.transportforireland.ie/fares/50-discount-for-young-adult-and-student-leap-card-holders-on-commercial-bus-operators/', array['transport','discount','coach']::text[], null, 50, 'ubp', 'published'),
  ('discounts', 'UNiDAYS', 'Free student discount platform. Verify once a year.', 'UNiDAYS is free. Register with your personal email and verify your student status. Many colleges verify you instantly, or you can send in a student ID card. You get 12 months of access, then you re-verify. You cannot re-verify once you leave your college. Offers change often, so check the brand page before you buy. Checked November 2026. Confirm details on the official page.', 'https://www.myunidays.com/IE/en-IE', array['discount','online','free']::text[], null, 60, 'ubp', 'published'),
  ('discounts', 'Student Beans', 'Free student discounts for students and apprentices.', 'Discounts are for people in full-time education with a personal college email or a student iD. That includes university students and apprentices. If your email domain is recognised you are verified straight away. You re-verify every year. Use a code online or show your Student Beans iD in store. Checked November 2026. Confirm details on the official page.', 'https://www.studentbeans.com/ie/how-it-works', array['discount','online','apprentice','free']::text[], null, 70, 'ubp', 'published'),
  ('discounts', 'ISIC student card', 'International student ID with a discounts app.', 'ISIC is an international student ID. You can order it through isic.ie and use the app for a digital card. Its Discounts in Ireland page lists offers across entertainment, leisure, sport and travel. For Irish Rail and TFI student fares you need a Leap card, not an ISIC. Checked November 2026. Confirm details on the official page.', 'https://www.isic.ie/', array['discount','id','travel']::text[], null, 80, 'ubp', 'published'),
  ('discounts', 'Spotify Premium Student', '6.99 euro a month after a free first month.', 'You must be 18 or over and at an eligible higher-education college. Spotify uses SheerID to check you. It is not offered if you have already tried Premium. You can keep the student plan for up to four years. After that you move to Premium Individual. Checked November 2026. Confirm details on the official page.', 'https://www.spotify.com/ie/student/', array['discount','music','subscription']::text[], null, 90, 'ubp', 'published'),
  ('discounts', 'Apple Music student plan', '6.99 euro a month after a free first month.', 'Verify your student status and you keep student pricing for up to four years while you stay a student. After that the price moves to the individual rate. Free Apple TV for students ends when you stop qualifying. The offer does not work with Family Sharing. Checked November 2026. Confirm details on the official page.', 'https://www.apple.com/ie/apple-music/', array['discount','music','subscription']::text[], null, 100, 'ubp', 'published'),
  ('discounts', 'IFI 25 and Under card', '5 euro tickets at the Irish Film Institute for ages 16 to 25.', 'The 25 and Under card gives 5 euro cinema tickets to 16 to 25 year olds at IFI screenings. Online booking with the card is for people aged 18 and over, one ticket per person. Third-level students can also use concession prices, and concession membership costs 25 euro. Checked November 2026. Confirm details on the official page.', 'https://ifi.ie/visit/ticket-prices/', array['discount','cinema','dublin']::text[], null, 110, 'ubp', 'published'),
  ('discounts', 'Bank of Ireland Third Level account', 'No monthly maintenance fee while you study.', 'You must be 18 or over, in full-time third-level education in Ireland and living in the Republic, or moving there within 45 days. After graduation you get two years with no monthly fee. There is no overdraft on this account, and the bank points to student loans instead. Cash can be lodged or withdrawn at An Post offices. Checked November 2026. Confirm details on the official page.', 'https://personalbanking.bankofireland.com/bank/current-accounts/3rd-level-current-account/', array['banking','discount','account']::text[], null, 120, 'ubp', 'published'),
  ('discounts', 'AIB Student Plus account', 'Student account with an interest-free overdraft.', 'AIB''s fee document lists no account maintenance fee and no overdraft facility fee. It lists interest-free overdrafts of up to 1,000 euro in first and second year and 1,500 euro in third and fourth year. Anything over that is charged at the bank''s standard rate. Tell staff you hold the account to get the benefits in branch. Checked November 2026. Confirm details on the official page.', 'https://www.aib.ie/our-products/current-accounts/Student-Plus-AccTerms-Cons', array['banking','discount','account']::text[], null, 130, 'ubp', 'published'),
  ('support', 'Pieta', 'Free support for suicidal thoughts, self-harm and bereavement.', 'Pieta offers free therapy without a referral, a 24-hour crisis helpline and support for people bereaved by suicide. Crisis helpline: 1800 247 247. Crisis text: text HELP to 51444. Therapy services: 0818 111 126. You can also call if you are worried about someone else. If you are in danger right now, call 999 or 112. Checked November 2026. Confirm details on the official page.', 'https://www.pieta.ie/', array['mental-health','crisis','free','24-hour']::text[], null, 10, 'ubp', 'published'),
  ('support', 'Samaritans Ireland', 'Free, listening support any time, day or night.', 'Call 116 123 for free. They are there 24 hours a day, 365 days a year. If you are in danger right now, call 999 or 112. Checked November 2026. Confirm details on the official page.', 'https://www.samaritans.org/ireland/', array['mental-health','crisis','free','24-hour']::text[], null, 20, 'ubp', 'published'),
  ('support', 'Text About It (50808)', 'Free text line for anything on your mind. Runs 24/7.', 'Text HELLO to 50808 to start a conversation with a trained volunteer. It is run by SpunOut.ie and funded by the HSE. It is anonymous and free on the main networks. Some customers on smaller networks need to text 086 1800 280 instead, and standard rates may apply. It is not for emergencies. If you are in danger right now, call 999 or 112. Checked November 2026. Confirm details on the official page.', 'https://spunout.ie/services/text-about-it/', array['mental-health','text','free','24-hour','young-people']::text[], null, 30, 'ubp', 'published'),
  ('support', 'Jigsaw', 'Free online mental health support for young people.', 'Jigsaw is the National Centre for Youth Mental Health. Its online service offers text chat with a therapist, one-to-one or in a group, plus email support. The online service is free. You can also find your local Jigsaw on their site. Phone: 01 472 7010. Checked November 2026. Confirm details on the official page.', 'https://jigsaw.ie/', array['mental-health','young-people','free','online']::text[], null, 40, 'ubp', 'published'),
  ('support', 'Aware', 'Support for depression, bipolar disorder and anxiety.', 'Aware runs a Support Line on 1800 80 48 48. It also offers support and self-care groups, a free out-of-hours Solace Cafe in Dublin and Waterford, counselling and information. Check the site for the support line hours. Checked November 2026. Confirm details on the official page.', 'https://www.aware.ie/', array['mental-health','support-groups','helpline']::text[], null, 50, 'ubp', 'published'),
  ('support', 'Turn2me', 'Online counselling and peer support groups.', 'Turn2me offers one-to-one online counselling by video or text chat. The page says there are 6 free counselling sessions for Irish residents, for people aged 18 and over. Anonymous peer support groups are free to join. Checked November 2026. Confirm details on the official page.', 'https://www.turn2me.ie/', array['mental-health','counselling','online','free']::text[], null, 60, 'ubp', 'published'),
  ('support', 'MyMind', 'Low-cost counselling, online or in person.', 'MyMind is a not-for-profit counselling and psychotherapy service. It has a reduced rate for full-time third-level students. Its student page is dated, so check the price on the site before you book. There is no referral and no waiting list, according to MyMind. Checked November 2026. Confirm details on the official page.', 'https://mymind.org/counselling-for-students-1', array['mental-health','counselling','low-cost']::text[], null, 70, 'ubp', 'published'),
  ('support', 'Childline', 'Free listening service for children and young people.', 'Call 1800 66 66 66 for free, or chat online. The chat is open 24 hours a day, every day. You can talk about anything. Checked November 2026. Confirm details on the official page.', 'https://www.childline.ie/', array['young-people','helpline','free','24-hour']::text[], null, 80, 'ubp', 'published'),
  ('support', 'HSE Your Mental Health information line', 'Free line to find the right mental health service.', 'Call 1800 111 888 any time. It is free. They can point you to HSE mental health supports and services, and how to access them. The yourmentalhealth.ie site lists services nationally and locally. Checked November 2026. Confirm details on the official page.', 'https://www.hse.ie/mental-health/services-support/your-mental-health-information-line/', array['mental-health','helpline','free','HSE']::text[], null, 90, 'ubp', 'published'),
  ('support', 'Women''s Aid', 'Free, confidential helpline for domestic abuse.', 'The 24-hour National Freephone Helpline is 1800 341 900. It is free and confidential. Women''s Aid also offers instant message support, mornings and evenings, seven days a week. Its page also lists support for young people, men and LGBTI+ people. If you are in danger right now, call 999 or 112. Checked November 2026. Confirm details on the official page.', 'https://www.womensaid.ie/', array['safety','domestic-abuse','helpline','free','24-hour']::text[], null, 100, 'ubp', 'published'),
  ('support', 'Dublin Rape Crisis Centre', '24-hour helpline and webchat after sexual violence.', 'The National 24-Hour Helpline is 1 800 77 8888, a freephone number. There is also a confidential webchat. The site has a guide called Finding Your Way after Sexual Violence. If you are in danger right now, call 999 or 112. Checked November 2026. Confirm details on the official page.', 'https://www.drcc.ie/', array['safety','sexual-violence','helpline','24-hour']::text[], null, 110, 'ubp', 'published'),
  ('support', 'BeLonG To', 'Support for LGBTQ+ young people.', 'BeLonG To is the national organisation supporting LGBTQ+ young people. It lists a one-on-one chat service, professional counselling, a drug and alcohol support service, youth groups and family support. The page does not list a cost or a phone number, so use the contact page. Checked November 2026. Confirm details on the official page.', 'https://www.belongto.org/', array['lgbtq','young-people','counselling']::text[], null, 120, 'ubp', 'published'),
  ('support', 'Student Assistance Fund (money help)', 'Hardship fund through your college. Free to apply.', 'If money is the problem, the Student Assistance Fund can help with books, rent, food, travel, childcare and medical costs. It does not cover tuition or registration fees. Ask the access or student services office at your college. Your application is handled confidentially. Checked November 2026. Confirm details on the official page.', 'https://hea.ie/funding-governance-performance/funding/student-finance/student-assistance-fund/', array['money','hardship','college']::text[], null, 130, 'ubp', 'published'),
  ('support', 'MABS money advice', 'Free, confidential help with money and debt.', 'MABS is a free, independent and confidential service. It gives non-judgemental advice on managing money and problem debt. Helpline: 0818 07 2000, Monday to Friday, 9am to 8pm. Checked November 2026. Confirm details on the official page.', 'https://www.citizensinformationboard.ie/en/services/mabs/', array['money','debt','helpline','free']::text[], null, 140, 'ubp', 'published'),
  ('support', 'Citizens Information phone service', 'Free information on public services and your rights.', 'Call 0818 07 4000, Monday to Friday, 9am to 8pm. It is a confidential information service. Calls to 0818 numbers cost no more than a landline call. There is also a Live Advisor chat for people who find phone calls hard, 9am to 5pm Monday to Friday. Checked November 2026. Confirm details on the official page.', 'https://www.citizensinformationboard.ie/en/services/citizensinformation/cips.html', array['information','rights','helpline']::text[], null, 150, 'ubp', 'published'),
  ('support', 'RTB student renting guide', 'Know your rights as a student tenant.', 'The Residential Tenancies Board explains deposits, rent receipts, registration and disputes for students. Get a written deposit receipt and keep proof of every payment. Digs and short-term lets are not covered by RTB dispute resolution. Talk to your landlord first, then use the RTB if it is not fixed. Checked November 2026. Confirm details on the official page.', 'https://rtb.ie/students/', array['housing','renting','rights']::text[], null, 160, 'ubp', 'published'),
  ('support', 'Threshold', 'Housing and renting advice.', 'Threshold is a housing charity that gives advice to renters. It describes its advice as free and confidential. Visit threshold.ie to get help. Checked November 2026. Confirm details on the official page.', 'https://threshold.ie/', array['housing','renting','free']::text[], null, 170, 'ubp', 'published'),
  ('support', 'Your college counselling service', 'Often free for students. Ask your student services.', 'Many colleges run a student counselling service. Trinity''s service, for example, is free and confidential. Search your college site for counselling, student health or wellbeing. If you are not sure where to start, ask your Students'' Union.', null, array['mental-health','college','counselling']::text[], null, 180, 'ubp', 'published'),
  ('societies', 'UL Law Society', 'University of Limerick. Law society.', 'Listed on the University of Limerick societies list. Check the list for how to join. Checked November 2026. Confirm details on the official page.', 'https://www.ulwolves.ie/societies', array['law','academic']::text[], 'University of Limerick', 10, 'ubp', 'published'),
