  ('societies', 'Galway St. Vincent de Paul Society', 'University of Galway. Charity and volunteering society.', 'Listed on the University of Galway societies list. Join through the societies site with your student login. Checked November 2026. Confirm details on the official page.', 'https://socs.universityofgalway.ie/societies/', array['charity','volunteering']::text[], 'University of Galway', 160, 'ubp', 'published'),
