  ('societies', 'UCC Law Society', 'University College Cork. Law society.', 'Listed on the University College Cork societies list. Check the list for how to join. Checked November 2026. Confirm details on the official page.', 'https://www.ucc.ie/en/societies/allsocieties/', array['law','academic']::text[], 'University College Cork', 180, 'ubp', 'published'),
